// src/App.tsx
import React from 'react';
import CatalogItemForm from './catalog/components/CatalogItemForm';
import CreatorAuthorityForm from './catalog/components/CreatorAuthorityForm';
import CollectionsCatalog from './catalog/components/CollectionsCatalog';
import CreatorsListViewer from './catalog/components/creators_list_viewer';


function App() {
  const [currentView, setCurrentView] = React.useState('collections');

  return (
    <div className="App">
      <nav className="p-4 bg-amber-900 text-white flex gap-3">
        <button onClick={() => setCurrentView('collections')} className="underline-offset-2 hover:underline">Collections</button>
        <button onClick={() => setCurrentView('catalog')} className="underline-offset-2 hover:underline">Catalog Items</button>
        <button onClick={() => setCurrentView('list_creators')} className="underline-offset-2 hover:underline">Creators List</button>
        <button onClick={() => setCurrentView('creators')} className="underline-offset-2 hover:underline">Creators</button>
      </nav>
      
      {currentView === 'collections' && <CollectionsCatalog />}
      {currentView === 'catalog' && <CatalogItemForm />}
      {currentView === 'list_creators' && <CreatorsListViewer />}
      {currentView === 'creators' && <CreatorAuthorityForm />}
    </div>
  );
}

export default App;